return {
    containsSpace = function(p1) -- containsSpace | line: 4
        return #{ string.match(p1, "%s") } ~= 0
    end,
    stripQuotes = function(p2) -- stripQuotes | line: 7
        return (string.gsub(string.gsub(p2, "^(['\"])", ""), "(['\"])%s*$", ""))
    end,
    getQuoteChar = function(p3) -- getQuoteChar | line: 10
        return (string.match(p3, "^(['\"])"))
    end,
    isQuoteStarted = function(p4) -- isQuoteStarted | line: 13
        return string.match(p4, "^(['\"])") ~= nil
    end,
    isQuoteEnded = function(p5) -- isQuoteEnded | line: 16
        return string.match(p5, "(['\"])%s*$") ~= nil
    end
}
